    if (this.initialized) return;

    try {
      if (process.env.NODE_ENV === 'production') {
        // In production, use cloud secrets manager
        await this.loadFromCloud();
      } else {
        // In development/test, use environment variables
        await this.loadFromEnv();
      }

      this.initialized = true;
      console.log('Secrets manager initialized successfully');
    } catch (error) {
      console.error('Failed to initialize secrets manager:', error.message);
      throw error;
    }
  }

  async loadFromCloud() {
    // Implementation for AWS Secrets Manager
    // const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
