    const requiredSecrets = ['JWT_SECRET'];
    const optionalSecrets = ['DB_PASSWORD', 'STRIPE_SECRET_KEY', 'AWS_ACCESS_KEY_ID'];

    for (const secretName of [...requiredSecrets, ...optionalSecrets]) {
      if (process.env[secretName]) {
