      }
    }

    // Validate required secrets
    for (const secretName of requiredSecrets) {
      if (!this.secrets.has(secretName)) {
        throw new Error(`Missing required secret: ${secretName}`);
      }
    }
  }

  get(secretName) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized');
    }

    const secret = this.secrets.get(secretName);
    if (!secret) {
      throw new Error(`Secret not found: ${secretName}`);
    }

    return secret;
  }

  // Rotate secret (for production use)
  async rotateSecret(secretName, newValue) {
    if (process.env.NODE_ENV === 'production') {
      // In production, update cloud secrets manager
      console.log(`Rotating secret: ${secretName}`);
      // Actual implementation would update cloud provider
    }

    this.secrets.set(secretName, newValue);
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

