// Secure secrets management utility
const { execSync } = require('child_process');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.initialized = false;
  }

  // Initialize secrets based on environment
  async init() {
    const env = process.env.NODE_ENV || 'development';

    switch (env) {
      case 'production':
        await this.loadProductionSecrets();
        break;
      case 'test':
        await this.loadTestSecrets();
        break;
      case 'development':
      default:
        await this.loadDevelopmentSecrets();
        break;
    }

    this.initialized = true;
    console.log(`Secrets initialized for ${env} environment`);
  }

  // Production: Load from secure sources (AWS Secrets Manager, Kubernetes, etc.)
  async loadProductionSecrets() {
    try {
      // Example: AWS Secrets Manager (uncomment and configure as needed)
      /*
      const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
      const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
      const command = new GetSecretValueCommand({ SecretId: process.env.SECRETS_NAME });
      const response = await client.send(command);
      this.secrets = JSON.parse(response.SecretString);
      */

      // Fallback: Use environment variables (set by your deployment platform)
      this.secrets = {
        databaseUrl: process.env.DATABASE_URL,
        awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
        awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        stripeSecretKey: process.env.STRIPE_SECRET_KEY,
        apiKeys: {
          anthropic: process.env.ANTHROPIC_API_KEY,
          logfire: process.env.LOGFIRE_TOKEN
        }
      };

    } catch (error) {
      console.error('Failed to load production secrets:', error.message);
      throw new Error('Secrets configuration error');
    }
  }

  // Test: Load from encrypted test secrets or mock data
  async loadTestSecrets() {
    // For tests, use mock credentials or encrypted test secrets
    this.secrets = {
      databaseUrl: process.env.DATABASE_URL || 'sqlite://:memory:',
      awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID || 'test-aws-key',
      awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || 'test-aws-secret',
      stripeSecretKey: process.env.STRIPE_SECRET_KEY || 'REDACTED_STRIPE_TEST',
      apiKeys: {
        anthropic: process.env.ANTHROPIC_API_KEY || 'test-api-key',
        logfire: process.env.LOGFIRE_TOKEN || 'test-log-token'
      }
    };
  }

  // Development: Load from local .env file
  async loadDevelopmentSecrets() {
    // Already loaded via dotenv, just map to our structure
    this.secrets = {
      databaseUrl: process.env.DATABASE_URL,
      awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
      awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      stripeSecretKey: process.env.STRIPE_SECRET_KEY,
      apiKeys: {
        anthropic: process.env.ANTHROPIC_API_KEY,
        logfire: process.env.LOGFIRE_TOKEN
      }
    };
  }

  // Get a secret with validation
  getSecret(key, defaultValue = null) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized');
    }

    const value = this._getNestedValue(this.secrets, key);

    if (value === undefined || value === null) {
      if (defaultValue !== null) {
        return defaultValue;
      }
      throw new Error(`Secret not found: ${key}`);
    }

    return value;
  }

  // Helper to get nested object values
  _getNestedValue(obj, path) {
    return path.split('.').reduce((acc, part) => {
      return acc && acc[part] !== undefined ? acc[part] : undefined;
    }, obj);
  }

  // Validate all required secrets are present
  validateSecrets(requiredSecrets) {
    const missing = [];

    requiredSecrets.forEach(secretPath => {
      if (this.getSecret(secretPath, undefined) === undefined) {
        missing.push(secretPath);
      }
    });

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    return true;
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

