# Security Improvements for app.js

## 1. Input Validation & Sanitization

### Current Issue: Missing comprehensive input validation
```javascript
// Before: Minimal validation
app.get('/users', (req, res) => {
  // No proper input sanitization
  const limit = req.query.limit; // Potential injection risk
});
```

### Recommended Fix:
```javascript
// Enhanced input validation with express-validator
const { body, query, validationResult } = require('express-validator');

app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 })
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Safe to use validated input
  const limit = parseInt(req.query.limit) || 10;
});
```

## 2. Authentication Implementation

### Current Issue: No authentication mechanism
```javascript
// Missing authentication middleware
app.get('/users', (req, res) => {
  // No user authentication check
});
```

### Recommended Fix:
```javascript
// JWT authentication middleware
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// Protected route
app.get('/users', authenticateToken, (req, res) => {
  // Only accessible with valid JWT
});
```

## 3. SQL Injection Prevention

### Current Issue: No database operations, but pattern needed
```javascript
// If adding database operations, need parameterized queries
// const userId = req.params.id; // UNSAFE if concatenated
```

### Recommended Fix:
```javascript
// Using parameterized queries with database library
app.get('/users/:id', authenticateToken, async (req, res) => {
  try {
    // SAFE: Parameterized query
    const user = await db.query(
      'SELECT * FROM users WHERE id = $1',
      [req.params.id] // Parameter prevents SQL injection
    );

    res.json(user);
  } catch (error) {
    res.status(500).json({ error: 'Database error' });
  }
});
```

## 4. XSS Prevention

### Current Issue: No output encoding
```javascript
// Potential XSS if user input is reflected
app.get('/search', (req, res) => {
  const query = req.query.q;
  // UNSAFE: res.send(`Search results for: ${query}`);
});
```

### Recommended Fix:
```javascript
// Using dedicated XSS prevention library
const xss = require('xss');

app.get('/search', (req, res) => {
  const query = req.query.q;
  // SAFE: XSS filtering
  const safeQuery = xss(query);
  res.send(`Search results for: ${safeQuery}`);
});
```

## 5. Environment Security

### Current Issue: Insecure environment configuration
```javascript
// Environment-specific security settings needed
```

### Recommended Fix:
```javascript
// Production-specific security enhancements
if (process.env.NODE_ENV === 'production') {
  // Additional security headers
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'", "'unsafe-inline'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", "data:", "https:"],
      },
    },
  }));

  // Stricter rate limiting in production
  app.use(rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 50, // Lower limit for production
  }));
}
```

## Required Dependencies
```bash
npm install express-validator jsonwebtoken bcryptjs xss
```

// Secure version of app.js with security improvements
require('dotenv').config({ path: process.env.NODE_ENV === 'test' ? '.env.test' : '.env' });

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const xss = require('xss');

const app = express();

// Environment configuration
const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = process.env.PORT || 3000;

// Custom error handler
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    url: req.originalUrl,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  if (NODE_ENV === 'production') {
    return res.status(500).json({ error: 'Internal Server Error' });
  }

  res.status(500).json({ error: err.message });
};

// Security middleware with CSP
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

// CORS configuration
app.use(cors({
  origin: NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:5173'],
  credentials: true
}));

// Rate limiting (stricter in production)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: NODE_ENV === 'production' ? 50 : 100,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// JWT Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// Health endpoint (public)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV 
  });
});

// Users endpoint with authentication and validation
app.get('/users', [
  authenticateToken,
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer')
], (req, res) => {
  try {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Search endpoint with XSS protection
app.get('/search', [
  query('q').trim().escape() // XSS prevention
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const query = req.query.q;
  const safeQuery = xss(query); // Additional XSS protection

  res.json({ 
    results: [], 
    query: safeQuery,
    message: 'Search functionality placeholder'
  });
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Error handling middleware
app.use(errorHandler);

app.listen(PORT, () => {
  console.log(`Server running in ${NODE_ENV} mode on port ${PORT}`);
});

module.exports = app;

