// AWS Secrets Manager example
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getDatabaseConfig() {
    return this.getSecret('production/database');
  }

  async getApiSecrets() {
    return this.getSecret('production/api');
  }

  async getJwtConfig() {
    return this.getSecret('production/jwt');
  }
}

module.exports = SecretsManager;

// Secure configuration loader with fallbacks
const fs = require('fs').promises;
const path = require('path');

class ConfigLoader {
  constructor() {
    this.config = {};
    this.secretsManager = null;
  }

  async initialize() {
    // Load basic environment variables first
    await this.loadEnvConfig();

    // Initialize secrets manager based on environment
    if (process.env.NODE_ENV === 'production') {
      await this.initializeSecretsManager();
      await this.loadSecrets();
    } else {
      // For development/staging, use encrypted local secrets
      await this.loadLocalSecrets();
    }
  }

  async loadEnvConfig() {
    // Load from environment variables (set by deployment system)
    this.config.port = process.env.PORT || 3000;
    this.config.nodeEnv = process.env.NODE_ENV || 'development';
    this.config.allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || [];
  }

  async initializeSecretsManager() {
    try {
      // Lazy load AWS SDK only when needed
      const { SecretsManager } = require('./secrets-manager');
      this.secretsManager = new SecretsManager();
    } catch (error) {
      console.error('Failed to initialize secrets manager:', error);
      throw error;
    }
  }

  async loadSecrets() {
    try {
      const apiSecrets = await this.secretsManager.getApiSecrets();
      const jwtConfig = await this.secretsManager.getJwtConfig();

      this.config.apiSecret = apiSecrets.API_SECRET;
      this.config.jwtSecret = jwtConfig.JWT_SECRET;
      this.config.databaseUrl = apiSecrets.DATABASE_URL;

    } catch (error) {
      console.error('Failed to load secrets:', error);
      // Fallback to environment variables if secrets manager fails
      this.config.apiSecret = process.env.API_SECRET;
      this.config.jwtSecret = process.env.JWT_SECRET;
      this.config.databaseUrl = process.env.DATABASE_URL;
    }
  }

  async loadLocalSecrets() {
    // For development, use encrypted local file or environment variables
    try {
      // Try to load from encrypted file if exists
      const secretsPath = path.join(__dirname, 'secrets.encrypted');
      try {
        await fs.access(secretsPath);
        // In real implementation, decrypt the file
        this.config.apiSecret = process.env.API_SECRET || 'dev-secret-key';
        this.config.jwtSecret = process.env.JWT_SECRET || 'dev-jwt-secret';
      } catch {
        // Fallback to environment variables
        this.config.apiSecret = process.env.API_SECRET || 'dev-secret-key';
        this.config.jwtSecret = process.env.JWT_SECRET || 'dev-jwt-secret';
        this.config.databaseUrl = process.env.DATABASE_URL;
      }
    } catch (error) {
      console.warn('Using development defaults for secrets');
      this.config.apiSecret = 'dev-secret-key';
      this.config.jwtSecret = 'dev-jwt-secret';
    }
  }

  get(key) {
    return this.config[key];
  }

  getAll() {
    return { ...this.config };
  }
}

// Singleton instance
const configLoader = new ConfigLoader();

module.exports = {
  configLoader,
  getConfig: () => configLoader.getAll(),
  get: (key) => configLoader.get(key)
};

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const { configLoader } = require('./config-loader');

async function createApp() {
  // Initialize configuration first
  await configLoader.initialize();
  const config = configLoader.getAll();

  const app = express();

  // Security middleware
  app.use(helmet());
  app.use(cors({
    origin: config.allowedOrigins.length > 0 
      ? config.allowedOrigins 
      : ['http://localhost:3000'],
    credentials: true
  }));
  app.use(express.json({ limit: '10kb' }));

  // Rate limiting - configurable from environment
  const limiter = rateLimit({
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000,
    max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use(limiter);

  // Secure authentication middleware
  const requireAuth = (req, res, next) => {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    const token = authHeader.substring(7);

    // Use config from secrets manager
    if (token !== config.apiSecret) {
      return res.status(401).json({ error: 'Invalid token' });
    }

    next();
  };

  // Health endpoint (public)
  app.get('/health', (req, res) => {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || '1.0.0',
      environment: config.nodeEnv
    });
  });

  // Protected users endpoint
  app.get('/users', requireAuth, (req, res) => {
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    res.json({
      data: users,
      count: users.length,
      timestamp: new Date().toISOString()
    });
  });

  // Protected endpoint with validation
  app.post('/users', [
    requireAuth,
    body('name').isLength({ min: 1, max: 100 }).trim().escape(),
    body('email').isEmail().normalizeEmail(),
  ], (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    res.status(201).json({ message: 'User created successfully' });
  });

  // Error handling middleware
  app.use((error, req, res, next) => {
    console.error('Error:', error);

    const response = config.nodeEnv === 'production' 
      ? { error: 'Something went wrong' }
      : { error: error.message };

    res.status(error.status || 500).json(response);
  });

  // 404 handler
  app.use('*', (req, res) => {
    res.status(404).json({ error: 'Endpoint not found' });
  });

  return app;
}

// Export both the app factory and the create function
module.exports = {
  createApp,
  configLoader
};

const { createApp } = require('./app_production_secured');

async function startServer() {
  try {
    const app = await createApp();
    const port = process.env.PORT || 3000;

    const server = app.listen(port, () => {
      console.log(`🚀 Secure server running on port ${port}`);
      console.log(`🌍 Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`🔐 Using secrets manager: ${process.env.NODE_ENV === 'production' ? 'Yes' : 'Development mode'}`);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('SIGTERM received, shutting down gracefully');
      server.close(() => {
        console.log('Server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
}

// Only start if run directly
if (require.main === module) {
  startServer();
}

module.exports = { startServer };

