// Secure secrets management with fallback strategies
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.secretsCache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes cache
  }

  // AWS Secrets Manager integration
  async getAWSSecret(secretName, region = 'us-east-1') {
    try {
      const client = new SecretsManagerClient({ region });
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await client.send(command);

      if (response.SecretString) {
        return JSON.parse(response.SecretString);
      }

      throw new Error('Secret not found in string format');
    } catch (error) {
      console.error(`AWS Secrets Manager error for ${secretName}:`, error.message);
      throw error;
    }
  }

  // Environment variable fallback with validation
  getEnvSecret(secretName, options = {}) {
    const {
      required = true,
      defaultValue = null,
      validate = null
    } = options;

    const value = process.env[secretName] || defaultValue;

    if (required && !value) {
      throw new Error(`Required secret ${secretName} is missing`);
    }

    if (validate && value && !validate(value)) {
      throw new Error(`Secret ${secretName} failed validation`);
    }

    return value;
  }

  // Cached secrets retrieval
  async getSecret(secretName, options = {}) {
    const cacheKey = `${secretName}_${process.env.NODE_ENV}`;

    // Check cache first
    const cached = this.secretsCache.get(cacheKey);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    let secretValue;

    // Try AWS Secrets Manager first (production)
    if (process.env.NODE_ENV === 'production' && process.env.AWS_SECRETS_ENABLED === 'true') {
      try {
        secretValue = await this.getAWSSecret(secretName);
      } catch (error) {
        console.warn('Falling back to environment variables for', secretName);
        secretValue = this.getEnvSecret(secretName, options);
      }
    } else {
      // Development/Staging - use environment variables
      secretValue = this.getEnvSecret(secretName, options);
    }

    // Cache the result
    this.secretsCache.set(cacheKey, {
      value: secretValue,
      timestamp: Date.now()
    });

    return secretValue;
  }

  // Clear cache (useful for secret rotation)
  clearCache() {
    this.secretsCache.clear();
  }
}

// Validators for common secret types
const validators = {
  jwtSecret: (value) => value && value.length >= 32,
  databaseUrl: (value) => value && value.startsWith('postgres://') || value.startsWith('mysql://'),
  apiKey: (value) => value && value.length >= 20,
  port: (value) => !isNaN(value) && value > 0 && value < 65536
};

module.exports = { SecretsManager, validators };

