  async initialize() {
    try {
      // Load secrets first
      await secretsManager.loadSecrets();

      // Load configuration
      this.loadConfig();

      console.log('✅ Configuration loaded successfully');
    } catch (error) {
      console.error('❌ Failed to load configuration:', error.message);
      process.exit(1);
    }
  }

  loadConfig() {
    this.config = {
      // Application
      env: process.env.NODE_ENV || 'development',
      port: parseInt(process.env.PORT) || 3000,

      // Security
      jwtSecret: secretsManager.getSecret('JWT_SECRET'),
      jwtExpire: process.env.JWT_EXPIRE || '1h',

      // Database (if used)
      databaseUrl: process.env.DATABASE_URL,

      // Rate limiting
      rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 60000,
      rateLimitMaxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,

      // CORS
      allowedOrigins: process.env.ALLOWED_ORIGINS 
        ? process.env.ALLOWED_ORIGINS.split(',').map(origin => origin.trim())
        : ['http://localhost:3000', 'http://localhost:3001'],

      // Logging
      logLevel: process.env.LOG_LEVEL || 'info',

      // Features flags
      enableRateLimiting: process.env.ENABLE_RATE_LIMITING !== 'false',
      enableCors: process.env.ENABLE_CORS !== 'false',
    };

    // Validate production configuration
    if (this.config.env === 'production') {
      this.validateProductionConfig();
    }
  }

  validateProductionConfig() {
    const productionChecks = [
      {
        condition: !this.config.jwtSecret || this.config.jwtSecret.length < 32,
        message: 'JWT_SECRET must be at least 32 characters in production'
      },
      {
        condition: this.config.allowedOrigins.includes('*'),
        message: 'CORS cannot use wildcard (*) in production'
      },
      {
        condition: this.config.databaseUrl && this.config.databaseUrl.includes('localhost'),
        message: 'Database URL cannot point to localhost in production'
      }
    ];

    const errors = productionChecks
      .filter(check => check.condition)
      .map(check => check.message);

    if (errors.length > 0) {
      throw new Error(`Production configuration errors:\n- ${errors.join('\n- ')}`);
    }
  }

  get(key) {
    const value = this.config[key];
    if (value === undefined) {
      throw new Error(`Configuration key '${key}' not found`);
    }
    return value;
  }

  getAll() {
    return { ...this.config };
  }

  // Safe getter that doesn't throw
  getSafe(key, defaultValue = null) {
    return this.config[key] ?? defaultValue;
  }
}

// Singleton instance
const config = new Config();

module.exports = config;

