#!/usr/bin/env node

const config = require('./config');

async function startServer() {
  try {
    // Initialize configuration and secrets
    await config.initialize();

    // Now import app after configuration is loaded
    const app = require('./app-secure');

    const PORT = config.get('port');

    app.listen(PORT, () => {
      console.log(`🚀 Secure server running on port ${PORT}`);
      console.log(`🌍 Environment: ${config.get('env')}`);
      console.log(`🔐 JWT configured: ${config.get('jwtSecret') ? 'Yes' : 'No'}`);

      // Security status
      if (config.get('env') === 'production') {
        console.log('✅ Production mode security checks passed');
      } else {
        console.warn('⚠️  Running in development mode - security features may be relaxed');
      }
    });

  } catch (error) {
    console.error('❌ Failed to start server:', error.message);
    process.exit(1);
  }
}

// Handle graceful shutdown
process.on('SIGINT', () => {
  console.log('\n🛑 Shutting down gracefully...');
  process.exit(0);
});

process.on('SIGTERM', () => {
  console.log('\n🛑 Received SIGTERM, shutting down...');
  process.exit(0);
});

// Start the server
startServer();

